def compute(vars):
    goodwill_intangibles = vars["v1"]
    unconsolidated_subsidiaries = vars["v2"]
    total_liabilities = vars["v3"]

    if total_liabilities == 0:
        return None

    combined_liabilities = goodwill_intangibles + unconsolidated_subsidiaries
    value = combined_liabilities / total_liabilities

    return {
        "value": value,
        "trace": {
            "combined_liabilities": combined_liabilities,
            "total_liabilities": total_liabilities,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
